def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    dd_count = 0
    my_def = 0
    opp_def = 0
    for a, b in history:
        if a == 'D' and b == 'D':
            dd_count += 1
        if a == 'D':
            my_def += 1
        if b == 'D':
            opp_def += 1

    if n >= 10 and opp_def > 0.8 * n:
        return 'D'

    if dd_count == 0 and opp_def == 0:
        if my_def == 0:
            if n >= 5:
                return 'D'
            else:
                return 'C'
        else:
            return 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    recent_len = min(10, n)
    recent = opp[n-recent_len:]
    recent_c = sum(1 for a in recent if a == 'C')
    recent_ratio = recent_c / recent_len

    if n >= 6:
        last6 = opp[-6:]
        if all(a == 'D' for a in last6):
            if rng.random() < 0.08:
                return 'C'
            return 'D'
        if all(a == 'C' for a in last6):
            return 'C'

    if n >= 2:
        if opp[-1] == 'D' and me[-1] == 'C':
            if recent_ratio > 0.6:
                if rng.random() < 0.7:
                    return 'C'
                return 'D'
            else:
                if rng.random() < 0.15:
                    return 'C'
                return 'D'
        if opp[-1] == 'D' and me[-1] == 'D':
            if n % 7 == 0 or recent_ratio > 0.35:
                return 'C'
            if rng.random() < 0.12:
                return 'C'
            return 'D'
        if opp[-1] == 'C':
            if len(history) >= 3:
                last3 = opp[-3:]
                if last3 == ['C', 'C', 'D'] and me[-1] == 'C':
                    return 'D'
            return 'C'

    return 'C'
